SELECT CASE WHEN duration_sec >= 451 THEN 'high' WHEN duration_sec >= 71 THEN 'mid' ELSE 'low' END AS duration_sec_bucket, MIN(event_time) AS first_event_time, ROUND(AVG(duration_sec), 2) AS avg_duration_sec FROM web_events WHERE duration_sec < 170 GROUP BY CASE WHEN duration_sec >= 451 THEN 'high' WHEN duration_sec >= 71 THEN 'mid' ELSE 'low' END HAVING ROUND(AVG(duration_sec), 2) > 54 ORDER BY duration_sec_bucket;
